<section class="card"><h2>Activity & Evidence</h2><p>Cleaning checklist <?=access_h($d['cleaning']['revision'])?> · Inspection checklist <?=access_h($d['inspection']['revision'])?></p><ol class="hk-history"><li><strong>Cleaning Started</strong><p><?=access_h($c['root']['actor_name'].' · '.display_date($c['root']['created_at']))?> UTC</p><?php if($d['restart_reason']):?><p><?=access_h($d['restart_reason'])?></p><?php endif?></li>
<?php foreach($c['history'] as $ev):?><li><strong><?=access_h(match($ev['kind']){'hk_progress'=>'Cleaning Progress Saved','hk_completed'=>'Cleaning Completed','hk_exception_requested'=>$ev['data']['owner_authorized']?'Owner Self-Inspection Authorized':'Self-Inspection Requested','hk_exception_decided'=>$ev['data']['decision']==='approve'?'Self-Inspection Authorized':'Self-Inspection Declined','hk_inspected'=>$ev['data']['decision']==='release'?'Room Inspected & Released':'Room Returned For Cleaning','hk_followup'=>'Owner Follow-Up Recorded',default=>'Attempt Superseded'})?></strong><p><?=access_h($ev['actor_name'].' · '.display_date($ev['created_at']))?> UTC</p>
<?php foreach(['reason','comment'] as $k)if(!empty($ev['data'][$k])):?><p><?=access_h($ev['data'][$k])?></p><?php endif?>
<?php if($ev['kind']==='hk_completed'):?><details><summary>Completed Cleaning Checklist</summary><?php foreach($d['cleaning']['sections'] as $sec):?><h3><?=access_h($sec['title'])?></h3><ul><?php foreach($sec['items'] as $item):?><li><?=access_h($item['text'])?></li><?php endforeach?></ul><?php endforeach?></details><?php endif?>
<?php if($ev['kind']==='hk_inspected'):?><p><?=$ev['data']['self']?'Self-inspection under recorded owner authority':'Independent inspection'?></p><ul><?php foreach($d['inspection']['sections'] as $sec)foreach($sec['items'] as $item):?><li><?=access_h($item['text'])?> · <?=$ev['data']['results'][$item['id']]==='pass'?'Pass':'Needs Attention'?></li><?php endforeach?></ul><?php endif?>
<?php if(isset($files[(int)$ev['id']])):?><a href="<?=access_h(access_url('finance-evidence.php?kind=housekeeping&id='.(int)$ev['id']))?>">Download Room Evidence</a><?php endif?></li><?php endforeach?></ol></section>
